-- Up Migration

-- Finer muscle regions on top of the 12 muscle groups. Every region belongs to
-- exactly one group, so group totals, filters and CSV are unchanged. One region
-- per group is its default: exercises without their own region rows (user-created
-- ones) count toward the default region of their primary group.
CREATE TABLE muscle_regions (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  slug text NOT NULL UNIQUE,
  name text NOT NULL,
  muscle_group_id uuid NOT NULL REFERENCES muscle_groups (id),
  sort_order integer NOT NULL,
  is_group_default boolean NOT NULL DEFAULT false
);

CREATE UNIQUE INDEX muscle_regions_group_default_idx
  ON muscle_regions (muscle_group_id)
  WHERE is_group_default;

CREATE TABLE exercise_muscle_regions (
  exercise_id uuid NOT NULL REFERENCES exercises (id) ON DELETE CASCADE,
  muscle_region_id uuid NOT NULL REFERENCES muscle_regions (id),
  role text NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (exercise_id, muscle_region_id),
  CONSTRAINT exercise_muscle_regions_role_check CHECK (role IN ('PRIMARY', 'SECONDARY'))
);

CREATE INDEX exercise_muscle_regions_region_role_idx
  ON exercise_muscle_regions (muscle_region_id, role, exercise_id);

INSERT INTO muscle_regions (id, slug, name, muscle_group_id, sort_order, is_group_default)
SELECT region.id::uuid, region.slug, region.name, muscle_groups.id, region.sort_order, region.is_group_default
FROM (VALUES
  ('00000000-0000-4000-8000-000000000101', 'chest_upper', 'Upper chest', 'chest', 1, false),
  ('00000000-0000-4000-8000-000000000102', 'chest_lower', 'Lower chest', 'chest', 2, true),
  ('00000000-0000-4000-8000-000000000103', 'delts_front', 'Front delts', 'shoulders', 3, true),
  ('00000000-0000-4000-8000-000000000104', 'delts_side', 'Side delts', 'shoulders', 4, false),
  ('00000000-0000-4000-8000-000000000105', 'delts_rear', 'Rear delts', 'shoulders', 5, false),
  ('00000000-0000-4000-8000-000000000106', 'lats', 'Lats', 'back', 6, false),
  ('00000000-0000-4000-8000-000000000107', 'upper_back', 'Upper back', 'back', 7, true),
  ('00000000-0000-4000-8000-000000000108', 'lower_back', 'Lower back', 'back', 8, false),
  ('00000000-0000-4000-8000-000000000109', 'traps', 'Traps', 'traps', 9, true),
  ('00000000-0000-4000-8000-000000000110', 'neck', 'Neck', 'traps', 10, false),
  ('00000000-0000-4000-8000-000000000111', 'biceps', 'Biceps', 'biceps', 11, true),
  ('00000000-0000-4000-8000-000000000112', 'triceps', 'Triceps', 'triceps', 12, true),
  ('00000000-0000-4000-8000-000000000113', 'forearms', 'Forearms', 'forearms', 13, true),
  ('00000000-0000-4000-8000-000000000114', 'abs', 'Abs', 'abs', 14, true),
  ('00000000-0000-4000-8000-000000000115', 'obliques', 'Obliques', 'abs', 15, false),
  ('00000000-0000-4000-8000-000000000116', 'glutes', 'Glutes', 'glutes', 16, true),
  ('00000000-0000-4000-8000-000000000117', 'abductors', 'Abductors', 'glutes', 17, false),
  ('00000000-0000-4000-8000-000000000118', 'quads', 'Quads', 'quads', 18, true),
  ('00000000-0000-4000-8000-000000000119', 'adductors', 'Adductors', 'quads', 19, false),
  ('00000000-0000-4000-8000-000000000120', 'hamstrings', 'Hamstrings', 'hamstrings', 20, true),
  ('00000000-0000-4000-8000-000000000121', 'calves', 'Calves', 'calves', 21, true)
) AS region(id, slug, name, group_slug, sort_order, is_group_default)
JOIN muscle_groups ON muscle_groups.slug = region.group_slug;

