INSERT INTO exercise_muscle_regions (exercise_id, muscle_region_id, role)
SELECT catalog.id, muscle_regions.id, 'PRIMARY'
FROM region_import catalog
JOIN exercises ON exercises.id = catalog.id AND exercises.created_by_user_id IS NULL
JOIN LATERAL jsonb_array_elements_text(catalog."primary") region_slug ON true
JOIN muscle_regions ON muscle_regions.slug = region_slug
ON CONFLICT (exercise_id, muscle_region_id) DO NOTHING;

INSERT INTO exercise_muscle_regions (exercise_id, muscle_region_id, role)
SELECT catalog.id, muscle_regions.id, 'SECONDARY'
FROM region_import catalog
JOIN exercises ON exercises.id = catalog.id AND exercises.created_by_user_id IS NULL
JOIN LATERAL jsonb_array_elements_text(catalog."secondary") region_slug ON true
JOIN muscle_regions ON muscle_regions.slug = region_slug
ON CONFLICT (exercise_id, muscle_region_id) DO NOTHING;

